#!/usr/bin/env python3
"""Parse application log files.

Expected line format:

    2026-08-01 12:00:00 INFO started
    <---- timestamp ---> <lvl> <-msg->

Lines that don't match are reported as malformed rather than silently dropped.
"""

import argparse
import json
import re
import sys
from dataclasses import dataclass, asdict
from datetime import datetime
from typing import Iterable, Iterator, Optional

LINE_RE = re.compile(
    r"^(?P<ts>\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})\s+"
    r"(?P<level>[A-Z]+)\s+"
    r"(?P<message>.*)$"
)

TS_FORMAT = "%Y-%m-%d %H:%M:%S"


@dataclass
class Entry:
    timestamp: datetime
    level: str
    message: str
    source: str
    lineno: int

    def as_dict(self) -> dict:
        d = asdict(self)
        d["timestamp"] = self.timestamp.strftime(TS_FORMAT)
        return d


@dataclass
class Malformed:
    text: str
    source: str
    lineno: int


def parse_line(line: str, source: str, lineno: int):
    """Return an Entry, or a Malformed if the line doesn't fit the format."""
    match = LINE_RE.match(line.rstrip("\n"))
    if not match:
        return Malformed(text=line.rstrip("\n"), source=source, lineno=lineno)
    return Entry(
        timestamp=datetime.strptime(match["ts"], TS_FORMAT),
        level=match["level"],
        message=match["message"].strip(),
        source=source,
        lineno=lineno,
    )


def parse_file(path: str) -> Iterator:
    """Yield Entry/Malformed objects for each non-blank line in `path`."""
    handle = sys.stdin if path == "-" else open(path, "r", encoding="utf-8", errors="replace")
    name = "<stdin>" if path == "-" else path
    try:
        for lineno, line in enumerate(handle, start=1):
            if not line.strip():
                continue
            yield parse_line(line, name, lineno)
    finally:
        if handle is not sys.stdin:
            handle.close()


def parse_files(paths: Iterable[str]) -> Iterator:
    for path in paths:
        yield from parse_file(path)


def matches(
    entry: Entry,
    levels: Optional[set],
    pattern: Optional[re.Pattern],
    since: Optional[datetime],
    until: Optional[datetime],
) -> bool:
    if levels and entry.level not in levels:
        return False
    if pattern and not pattern.search(entry.message):
        return False
    if since and entry.timestamp < since:
        return False
    if until and entry.timestamp > until:
        return False
    return True


def parse_timestamp_arg(value: str) -> datetime:
    for fmt in (TS_FORMAT, "%Y-%m-%d %H:%M", "%Y-%m-%d"):
        try:
            return datetime.strptime(value, fmt)
        except ValueError:
            continue
    raise argparse.ArgumentTypeError(
        f"invalid timestamp {value!r}; expected 'YYYY-MM-DD[ HH:MM[:SS]]'"
    )


def main(argv=None) -> int:
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("paths", nargs="+", metavar="LOG", help="log file(s); use - for stdin")
    ap.add_argument("--level", action="append", metavar="LEVEL",
                    help="only show this level (repeatable), e.g. --level WARN --level ERROR")
    ap.add_argument("--grep", metavar="REGEX", help="only show entries whose message matches REGEX")
    ap.add_argument("--since", type=parse_timestamp_arg, metavar="TS", help="only entries at or after TS")
    ap.add_argument("--until", type=parse_timestamp_arg, metavar="TS", help="only entries at or before TS")
    ap.add_argument("--json", action="store_true", help="emit entries as a JSON array")
    ap.add_argument("--summary", action="store_true", help="print counts per level instead of entries")
    args = ap.parse_args(argv)

    levels = {lvl.upper() for lvl in args.level} if args.level else None
    pattern = re.compile(args.grep) if args.grep else None

    entries, malformed = [], []
    for item in parse_files(args.paths):
        if isinstance(item, Malformed):
            malformed.append(item)
        elif matches(item, levels, pattern, args.since, args.until):
            entries.append(item)

    if args.summary:
        counts = {}
        for entry in entries:
            counts[entry.level] = counts.get(entry.level, 0) + 1
        if args.json:
            print(json.dumps({"counts": counts, "total": len(entries),
                              "malformed": len(malformed)}, indent=2))
        else:
            for level, count in sorted(counts.items(), key=lambda kv: (-kv[1], kv[0])):
                print(f"{level:<8} {count}")
            print(f"{'TOTAL':<8} {len(entries)}")
    elif args.json:
        print(json.dumps([e.as_dict() for e in entries], indent=2))
    else:
        for entry in entries:
            print(f"{entry.timestamp:%Y-%m-%d %H:%M:%S} {entry.level:<5} {entry.message}")

    for bad in malformed:
        print(f"{bad.source}:{bad.lineno}: malformed line: {bad.text!r}", file=sys.stderr)

    return 0


if __name__ == "__main__":
    sys.exit(main())
